    /**
     * Method to retrieve the Coverage via CoverageFetchOneSummary
     * @param 	summary CoverageFetchOneSummary 
     * @return 	CoverageFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Coverage getCoverage( CoverageFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "CoverageFetchOneSummary arg cannot be null" );
    	
    	Coverage entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Coverage
        	// --------------------------------------
        	CompletableFuture<Coverage> futureEntity = queryGateway.query(new FindCoverageQuery( new LoadCoverageFilter( summary.getCoverageId() ) ), ResponseTypes.instanceOf(Coverage.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Coverage with id " + summary.getCoverageId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


